def getWordsInLongestSubsequence(self, n, words, groups):
    def hamming(a, b):
        if len(a) != len(b): return -1
        return sum(x != y for x, y in zip(a, b))
    dp = [1] * n
    parent = [-1] * n
    for i in range(1, n):
        for j in range(i):
            if groups[i] != groups[j] and hamming(words[i], words[j]) == 1:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    parent[i] = j
    idx = max(range(n), key=lambda x: dp[x])
    res = []
    while idx != -1:
        res.append(words[idx])
        idx = parent[idx]
    return res[::-1]

