def minGroupsForValidAssignment(self, nums):
    from collections import Counter
    freq = Counter(nums)
    counts = list(freq.values())
    min_cnt = min(counts)
    for k in range(min_cnt, 0, -1):
        total = 0
        valid = True
        for c in counts:
            # c = a*(k+1) + b*k, need a+b groups, a>=0, b>=0
            q, r = divmod(c, k + 1)
            if r == 0:
