def numberOfWays(self, n, m, k):
    MOD = 10**9 + 7
    # 4 states: (same_row, same_col), (same_row, diff_col), (diff_row, same_col), (diff_row, diff_col)
    # Matrix exponentiation on 4x4 transition matrix
    def mat_mul(A, B):
        size = len(A)
        C = [[0]*size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                for p in range(size):
                    C[i][j] = (C[i][j] + A[i][p]*B[p][j]) % MOD
        return C
    def mat_pow(M, exp):
        size = len(M)
        result = [[int(i==j) for j in range(size)] for i in range(size)]
        while exp:
            if exp & 1:
                result = mat_mul(result, M)
            M = mat_mul(M, M)
            exp >>= 1
        return result
    # Transitions: from any cell, move to any cell in same row or same col (excluding self)
    T = [
        [0, m-1, n-1, 0],
        [1, m-2, 0, n-1],
        [1, 0, n-2, m-1],
        [0, 1, 1, n+m-4]
    ]
    res = mat_pow(T, k)
    return res[3][0]  # start at diff_row, diff_col -> reach same_row, same_col

