def maxProfit(self, prices, profits):
    n = len(prices)
    MAX_P = max(prices) + 2
    # BIT for prefix max
    left_max = [0] * MAX_P
    right_max = [0] * MAX_P
    def update(bit, i, val):
        while i < len(bit):
            bit[i] = max(bit[i], val)
            i += i & (-i)
    def query(bit, i):
        res = 0
        while i > 0:
            res = max(res, bit[i])
            i -= i & (-i)
        return res
    # suffix max for right side using reversed BIT
    def update_suffix(bit, i, val):
        i = MAX_P - 1 - i
        update(bit, i, val)
    def query_suffix(bit, i):
        i = MAX_P - 1 - i
        return query(bit, i)
    left_best = [0] * n
    for i in range(n):
        left_best[i] = query(left_max, prices[i] - 1)
        update(left_max, prices[i], profits[i])
    right_best = [0] * n
    for i in range(n-1, -1, -1):
        right_best[i] = query_suffix(right_max, prices[i] + 1)
        update_suffix(right_max, prices[i], profits[i])
    res = -1
