def distributeCandies(self, n, limit):
    def C2(x):
        return x * (x - 1) // 2 if x >= 2 else 0
    def at_least(k):
        # at least k children exceed limit
        rem = n - k * (limit + 1)
        if rem < 0:
            return 0
        from math import comb
        return comb(3, k) * C2(rem + 2)
    return at_least(0) - at_least(1) + at_least(2) - at_least(3)

def distributeCandies(self, n, limit):
