        node = trie
        for i in range(19, -1, -1):
            bit = (x >> i) & 1
            node = node[bit]
            node['cnt'] -= 1
    def query(x):
        node = trie
        res = 0
        for i in range(19, -1, -1):
            bit = (x >> i) & 1
            want = 1 - bit
            if want in node and node[want].get('cnt', 0) > 0:
                res |= (1 << i)
                node = node[want]
            elif bit in node and node[bit].get('cnt', 0) > 0:
                node = node[bit]
            else:
